    assert del_in(coll, ['x']) == {'a': 1}

def test_del_in_empty_path():
    coll = {'a': 1}
    assert del_in(coll, []) == {'a': 1}

def test_del_in_list():
    coll = {'a': [1, 2, 3]}
    result = del_in(coll, ['a', 1])
    assert result == {'a': [1, 3]}


